document.addEventListener('pointerdown', (e) => { if (e.target.closest && e.target.closest('button:not(.gdot):not(#sndSw button)')) SND.play('tap'); }, true);

// the sound and language controls are compact dropdowns in the header
const SND_ICONS = ['volume-x', 'volume-2', 'music'];
let openDd = null;
function closeDd() { if (openDd) { openDd.classList.remove('open'); openDd = null; } }
function buildDd(host, btnContent, items, current, onPick, label) {
  const keepOpen = openDd === host;
  const btn = el('button', { type: 'button', class: 'ddbtn', 'aria-haspopup': 'menu', 'aria-expanded': String(keepOpen), 'aria-label': label, title: label, onclick: (e) => { e.stopPropagation(); const was = host.classList.contains('open'); closeDd(); if (!was) { host.classList.add('open'); openDd = host; } btn.setAttribute('aria-expanded', String(!was)); } }, ...btnContent, icon('caret', 11, 'ddcaret'));
  const menu = el('div', { class: 'ddmenu', role: 'menu' }, ...items.map(([v, content, name]) => el('button', { type: 'button', role: 'menuitemradio', 'aria-checked': String(v === current), class: v === current ? 'on' : '', onclick: (e) => { e.stopPropagation(); closeDd(); onPick(v); } }, ...content)));
  host.replaceChildren(btn, menu);
  host.classList.toggle('open', keepOpen);
}
document.addEventListener('click', () => closeDd());
document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeDd(); });
function updateSndBtn() {
  const host = document.getElementById('sndDd'); if (!host) return;
  buildDd(host, [icon(SND_ICONS[SND.mode], 17)], [0, 1, 2].map((m) => [m, [icon(SND_ICONS[m], 17), el('span', {}, t('sndMode' + m))]]), SND.mode, (m) => { SND.setMode(m); updateSndBtn(); toast(t('sndMode' + m), 'low'); if (m > 0) setTimeout(() => SND.play('ready'), 60); }, t('sndMode' + SND.mode));
}
const LANG_NAMES = { en: ['EN', 'English'], zh: ['简体', '简体中文'], zht: ['繁體', '繁體中文'] };
function updateLangDd() {
  const host = document.getElementById('langDd'); if (!host) return;
  buildDd(host, [el('span', { class: 'ddlang' }, LANG_NAMES[lang][0])], Object.keys(LANG_NAMES).map((l) => [l, [el('b', {}, LANG_NAMES[l][0]), el('span', {}, LANG_NAMES[l][1])]]), lang, setLang, t('langLabel'));
}

