const giftEl = (k, size = 40) => { const w = el('span', { class: 'giftart' }); w.style.cssText = `display:inline-block;width:${size}px;height:${size}px;line-height:0`; w.innerHTML = uniqSvg(`<svg viewBox="0 0 48 48" width="100%" height="100%" aria-hidden="true">${GIFT_SVG[k] || ''}</svg>`); return w; };
